(function($) {
    "use strict";

    // Определение плагина counterUp
    $.fn.counterUp = function(options) {
        // Настройки по умолчанию
        var settings = $.extend({
            time: 400,          // Общее время анимации (в миллисекундах)
            delay: 10,          // Задержка между обновлениями числа (в миллисекундах)
            offset: 100,        // Процент от высоты элемента, при котором запускается анимация
            beginAt: 0,         // Начальное значение счетчика
            formatter: false,   // Функция для форматирования числа (например, добавление знака $)
            context: "window",  // Контекст для Waypoints (например, "window" или другой элемент)
            callback: function() {} // Функция, вызываемая после завершения анимации
        }, options);

        // Для каждого элемента, на котором вызывается плагин
        return this.each(function() {
            var $this = $(this);

            // Извлечение настроек из атрибутов data-* или использование значений по умолчанию
            var counter = {
                time: $(this).data("counterup-time") || settings.time,
                delay: $(this).data("counterup-delay") || settings.delay,
                offset: $(this).data("counterup-offset") || settings.offset,
                beginAt: $(this).data("counterup-beginat") || settings.beginAt,
                context: $(this).data("counterup-context") || settings.context
            };

            // Функция, которая создает массив чисел для анимации
            var counterUpper = function() {
                var nums = []; // Массив для хранения чисел анимации
                var divisions = counter.time / counter.delay; // Количество шагов анимации

                // Получение конечного числа из атрибута data-num или текста элемента
                var num = $(this).attr("data-num") ? $(this).attr("data-num") : $this.text();
                var isComma = /[0-9]+,[0-9]+/.test(num); // Проверка, содержит ли число запятые
                num = num.replace(/,/g, ""); // Удаление запятых для обработки

                // Определение количества десятичных знаков
                var decimalPlaces = (num.split(".")[1] || []).length;

                // Если начальное значение больше конечного, корректируем его
                if (counter.beginAt > num) counter.beginAt = num;

                // Проверка, является ли число временем (например, 01:30:00)
                var isTime = /[0-9]+:[0-9]+:[0-9]+/.test(num);
                if (isTime) {
                    // Преобразование времени в секунды
                    var times = num.split(":"), m = 1, s = 0;
                    while (times.length > 0) {
                        s += m * parseInt(times.pop(), 10);
                        m *= 60;
                    }
                }

                // Создание массива чисел для анимации
                for (var i = divisions; i >= counter.beginAt / num * divisions; i--) {
                    var newNum = parseFloat(num / divisions * i).toFixed(decimalPlaces);

                    // Если число представляет время, преобразуем его обратно в формат HH:MM:SS
                    if (isTime) {
                        newNum = parseInt(s / divisions * i);
                        var hours = parseInt(newNum / 3600) % 24;
                        var minutes = parseInt(newNum / 60) % 60;
                        var seconds = parseInt(newNum % 60, 10);
                        newNum = (hours < 10 ? "0" + hours : hours) + ":" +
                                 (minutes < 10 ? "0" + minutes : minutes) + ":" +
                                 (seconds < 10 ? "0" + seconds : seconds);
                    }

                    // Если число содержит запятые, добавляем их обратно
                    if (isComma) {
                        while (/(\d+)(\d{3})/.test(newNum.toString())) {
                            newNum = newNum.toString().replace(/(\d+)(\d{3})/, "$1,$2");
                        }
                    }

                    // Если указана функция форматирования, применяем ее
                    if (settings.formatter) {
                        newNum = settings.formatter.call(this, newNum);
                    }

                    // Добавляем число в массив
                    nums.unshift(newNum);
                }

                // Сохраняем массив чисел в данных элемента
                $this.data("counterup-nums", nums);
                $this.text(counter.beginAt); // Устанавливаем начальное значение

                // Функция для обновления числа
                var f = function() {
                    // Если массив чисел пуст, завершаем анимацию
                    if (!$this.data("counterup-nums")) {
                        settings.callback.call(this);
                        return;
                    }

                    // Обновляем текст элемента
                    $this.html($this.data("counterup-nums").shift());

                    // Если в массиве еще есть числа, продолжаем анимацию
                    if ($this.data("counterup-nums").length) {
                        setTimeout($this.data("counterup-func"), counter.delay);
                    } else {
                        // Очищаем данные и вызываем callback
                        $this.data("counterup-nums", null);
                        $this.data("counterup-func", null);
                        settings.callback.call(this);
                    }
                };

                // Сохраняем функцию обновления в данных элемента
                $this.data("counterup-func", f);
                setTimeout($this.data("counterup-func"), counter.delay); // Запуск анимации
            };

            // Использование Waypoints для запуска анимации при появлении элемента в области видимости
            $this.waypoint(function(direction) {
                counterUpper(); // Запуск анимации
                this.destroy(); // Уничтожение Waypoint, чтобы анимация не запускалась повторно
            }, { offset: counter.offset + "%", context: counter.context });
        });
    };
})(jQuery);